ValidationRule.errorConditionFormula:
AND(
    NOT($Permission.SW_Bypass_Validation_Rules),
    OR(
        AND(
            NOT(ISBLANK(MobilePhone)),
            NOT(
                REGEX(
                    MobilePhone,
                    "^[0-9]{10}$"
                )
            )
        ),
        AND(
            NOT(ISBLANK(Phone)),
            NOT(
                REGEX(
                    Phone,
                    "^[0-9]{10}$"
                )
            )
        )
    )
)
